    ma_DirectSoundEnumerateAProc        DirectSoundEnumerateA;
    ma_DirectSoundCaptureCreateProc     DirectSoundCaptureCreate;
    ma_DirectSoundCaptureEnumerateAProc DirectSoundCaptureEnumerateA;

