static void ma_backend_info__winmm(ma_device_backend_info* pBackendInfo)
{
    MA_ASSERT(pBackendInfo != NULL);
    pBackendInfo->pName = "WinMM";
}

static ma_result ma_context_init__winmm(ma_context* pContext, const void* pContextBackendConfig, void** ppContextState)
{
    ma_context_state_winmm* pContextStateWinMM;
    const ma_context_config_winmm* pContextConfigWinMM = (const ma_context_config_winmm*)pContextBackendConfig;
    ma_context_config_winmm defaultConfigWinMM;

    if (pContextConfigWinMM == NULL) {
        defaultConfigWinMM  = ma_context_config_winmm_init();
        pContextConfigWinMM = &defaultConfigWinMM;
    }

    (void)pContextConfigWinMM;

    pContextStateWinMM = (ma_context_state_winmm*)ma_calloc(sizeof(*pContextStateWinMM), ma_context_get_allocation_callbacks(pContext));
    if (pContextStateWinMM == NULL) {
        return MA_OUT_OF_MEMORY;
    }

    pContextStateWinMM->hWinMM = ma_dlopen(ma_context_get_log(pContext), "winmm.dll");
    if (pContextStateWinMM->hWinMM == NULL) {
        ma_free(pContextStateWinMM, ma_context_get_allocation_callbacks(pContext));
        return MA_NO_BACKEND;
    }

    pContextStateWinMM->waveOutGetNumDevs      = (MA_PFN_waveOutGetNumDevs     )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveOutGetNumDevs");
    pContextStateWinMM->waveOutGetDevCapsA     = (MA_PFN_waveOutGetDevCapsA    )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveOutGetDevCapsA");
    pContextStateWinMM->waveOutOpen            = (MA_PFN_waveOutOpen           )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveOutOpen");
    pContextStateWinMM->waveOutClose           = (MA_PFN_waveOutClose          )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveOutClose");
    pContextStateWinMM->waveOutPrepareHeader   = (MA_PFN_waveOutPrepareHeader  )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveOutPrepareHeader");
    pContextStateWinMM->waveOutUnprepareHeader = (MA_PFN_waveOutUnprepareHeader)ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveOutUnprepareHeader");
    pContextStateWinMM->waveOutWrite           = (MA_PFN_waveOutWrite          )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveOutWrite");
    pContextStateWinMM->waveOutReset           = (MA_PFN_waveOutReset          )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveOutReset");
    pContextStateWinMM->waveInGetNumDevs       = (MA_PFN_waveInGetNumDevs      )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInGetNumDevs");
    pContextStateWinMM->waveInGetDevCapsA      = (MA_PFN_waveInGetDevCapsA     )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInGetDevCapsA");
    pContextStateWinMM->waveInOpen             = (MA_PFN_waveInOpen            )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInOpen");
    pContextStateWinMM->waveInClose            = (MA_PFN_waveInClose           )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInClose");
    pContextStateWinMM->waveInPrepareHeader    = (MA_PFN_waveInPrepareHeader   )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInPrepareHeader");
    pContextStateWinMM->waveInUnprepareHeader  = (MA_PFN_waveInUnprepareHeader )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInUnprepareHeader");
    pContextStateWinMM->waveInAddBuffer        = (MA_PFN_waveInAddBuffer       )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInAddBuffer");
    pContextStateWinMM->waveInStart            = (MA_PFN_waveInStart           )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInStart");
    pContextStateWinMM->waveInReset            = (MA_PFN_waveInReset           )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hWinMM, "waveInReset");


    /* Advapi32.dll */
    pContextStateWinMM->hAdvapi32 = ma_dlopen(ma_context_get_log(pContext), "advapi32.dll");
    if (pContextStateWinMM->hAdvapi32 == NULL) {
        ma_dlclose(ma_context_get_log(pContext), pContextStateWinMM->hWinMM);
        ma_free(pContextStateWinMM, ma_context_get_allocation_callbacks(pContext));
        return MA_NO_BACKEND;
    }

    pContextStateWinMM->RegOpenKeyExA    = (MA_PFN_RegOpenKeyExA   )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hAdvapi32, "RegOpenKeyExA");
    pContextStateWinMM->RegCloseKey      = (MA_PFN_RegCloseKey     )ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hAdvapi32, "RegCloseKey");
    pContextStateWinMM->RegQueryValueExA = (MA_PFN_RegQueryValueExA)ma_dlsym(ma_context_get_log(pContext), pContextStateWinMM->hAdvapi32, "RegQueryValueExA");

    *ppContextState = pContextStateWinMM;

    return MA_SUCCESS;
}

static void ma_context_uninit__winmm(ma_context* pContext)
{
    ma_context_state_winmm* pContextStateWinMM = ma_context_get_backend_state__winmm(pContext);

    ma_dlclose(ma_context_get_log(pContext), pContextStateWinMM->hAdvapi32);
    ma_dlclose(ma_context_get_log(pContext), pContextStateWinMM->hWinMM);

    ma_free(pContextStateWinMM, ma_context_get_allocation_callbacks(pContext));
}


static ma_result ma_result_from_MMRESULT(MA_MMRESULT resultMM)
{
    switch (resultMM)
    {
        case MA_MMSYSERR_NOERROR:       return MA_SUCCESS;
        case MA_MMSYSERR_BADDEVICEID:   return MA_INVALID_ARGS;
        case MA_MMSYSERR_INVALHANDLE:   return MA_INVALID_ARGS;
        case MA_MMSYSERR_NOMEM:         return MA_OUT_OF_MEMORY;
        case MA_MMSYSERR_INVALFLAG:     return MA_INVALID_ARGS;
        case MA_MMSYSERR_INVALPARAM:    return MA_INVALID_ARGS;
        case MA_MMSYSERR_HANDLEBUSY:    return MA_BUSY;
        case MA_MMSYSERR_ERROR:         return MA_ERROR;
        default:                        return MA_ERROR;
    }
}

static char* ma_find_last_character(char* str, char ch)
{
    char* last;

    if (str == NULL) {
        return NULL;
    }

    last = NULL;
    while (*str != '\0') {
        if (*str == ch) {
            last = str;
        }

        str += 1;
    }

    return last;
}

static ma_uint32 ma_get_period_size_in_bytes(ma_uint32 periodSizeInFrames, ma_format format, ma_uint32 channels)
{
    return periodSizeInFrames * ma_get_bytes_per_frame(format, channels);
}


/*
Our own "WAVECAPS" structure that contains generic information shared between WAVEOUTCAPS2 and WAVEINCAPS2 so
we can do things generically and typesafely. Names are being kept the same for consistency.
*/
typedef struct
{
    CHAR szPname[MA_MAXPNAMELEN];
    DWORD dwFormats;
    WORD wChannels;
    GUID NameGuid;
} MA_WAVECAPSA;

static ma_result ma_get_best_info_from_formats_flags__winmm(DWORD dwFormats, WORD channels, WORD* pBitsPerSample, DWORD* pSampleRate)
{
    WORD bitsPerSample = 0;
    DWORD sampleRate = 0;

    if (pBitsPerSample) {
        *pBitsPerSample = 0;
    }
    if (pSampleRate) {
        *pSampleRate = 0;
    }

    if (channels == 1) {
        bitsPerSample = 16;
        if ((dwFormats & WAVE_FORMAT_48M16) != 0) {
            sampleRate = 48000;
        } else if ((dwFormats & WAVE_FORMAT_44M16) != 0) {
            sampleRate = 44100;
        } else if ((dwFormats & WAVE_FORMAT_2M16) != 0) {
            sampleRate = 22050;
        } else if ((dwFormats & WAVE_FORMAT_1M16) != 0) {
            sampleRate = 11025;
        } else if ((dwFormats & WAVE_FORMAT_96M16) != 0) {
            sampleRate = 96000;
        } else {
            bitsPerSample = 8;
            if ((dwFormats & WAVE_FORMAT_48M08) != 0) {
                sampleRate = 48000;
            } else if ((dwFormats & WAVE_FORMAT_44M08) != 0) {
                sampleRate = 44100;
            } else if ((dwFormats & WAVE_FORMAT_2M08) != 0) {
                sampleRate = 22050;
            } else if ((dwFormats & WAVE_FORMAT_1M08) != 0) {
                sampleRate = 11025;
            } else if ((dwFormats & WAVE_FORMAT_96M08) != 0) {
                sampleRate = 96000;
            } else {
                return MA_FORMAT_NOT_SUPPORTED;
            }
        }
    } else {
        bitsPerSample = 16;
        if ((dwFormats & WAVE_FORMAT_48S16) != 0) {
            sampleRate = 48000;
        } else if ((dwFormats & WAVE_FORMAT_44S16) != 0) {
            sampleRate = 44100;
        } else if ((dwFormats & WAVE_FORMAT_2S16) != 0) {
            sampleRate = 22050;
        } else if ((dwFormats & WAVE_FORMAT_1S16) != 0) {
            sampleRate = 11025;
        } else if ((dwFormats & WAVE_FORMAT_96S16) != 0) {
            sampleRate = 96000;
        } else {
            bitsPerSample = 8;
            if ((dwFormats & WAVE_FORMAT_48S08) != 0) {
                sampleRate = 48000;
            } else if ((dwFormats & WAVE_FORMAT_44S08) != 0) {
                sampleRate = 44100;
            } else if ((dwFormats & WAVE_FORMAT_2S08) != 0) {
                sampleRate = 22050;
            } else if ((dwFormats & WAVE_FORMAT_1S08) != 0) {
                sampleRate = 11025;
            } else if ((dwFormats & WAVE_FORMAT_96S08) != 0) {
                sampleRate = 96000;
            } else {
                return MA_FORMAT_NOT_SUPPORTED;
            }
        }
    }

    if (pBitsPerSample) {
        *pBitsPerSample = bitsPerSample;
    }
    if (pSampleRate) {
        *pSampleRate = sampleRate;
    }

    return MA_SUCCESS;
}

static ma_result ma_formats_flags_to_WAVEFORMATEX__winmm(DWORD dwFormats, WORD channels, MA_WAVEFORMATEX* pWF)
{
    ma_result result;

    MA_ASSERT(pWF != NULL);

    MA_ZERO_OBJECT(pWF);
    pWF->cbSize     = sizeof(*pWF);
    pWF->wFormatTag = WAVE_FORMAT_PCM;
    pWF->nChannels  = (WORD)channels;
    if (pWF->nChannels > 2) {
        pWF->nChannels = 2;
    }

    result = ma_get_best_info_from_formats_flags__winmm(dwFormats, channels, &pWF->wBitsPerSample, &pWF->nSamplesPerSec);
    if (result != MA_SUCCESS) {
        return result;
    }

    pWF->nBlockAlign     = (WORD)(pWF->nChannels * pWF->wBitsPerSample / 8);
    pWF->nAvgBytesPerSec = pWF->nBlockAlign * pWF->nSamplesPerSec;

    return MA_SUCCESS;
}

static ma_result ma_context_get_device_info_from_WAVECAPS(ma_context* pContext, MA_WAVECAPSA* pCaps, ma_device_info* pDeviceInfo)
{
    ma_context_state_winmm* pContextStateWinmm = (ma_context_state_winmm*)ma_context_get_backend_state(pContext);
    WORD bitsPerSample;
    ma_format format;
    DWORD sampleRate;
    ma_result result;

    MA_ASSERT(pContext != NULL);
    MA_ASSERT(pCaps != NULL);
    MA_ASSERT(pDeviceInfo != NULL);

    /*
    Name / Description

    Unfortunately the name specified in WAVE(OUT/IN)CAPS2 is limited to 31 characters. This results in an unprofessional looking
    situation where the names of the devices are truncated. To help work around this, we need to look at the name GUID and try
    looking in the registry for the full name. If we can't find it there, we need to just fall back to the default name.
    */

    /* Set the default to begin with. */
    ma_strncpy_s(pDeviceInfo->name, sizeof(pDeviceInfo->name), pCaps->szPname, (size_t)-1);

    /*
    Now try the registry. There's a few things to consider here:
    - The name GUID can be null, in which we case we just need to stick to the original 31 characters.
    - If the name GUID is not present in the registry we'll also need to stick to the original 31 characters.
    - I like consistency, so I want the returned device names to be consistent with those returned by WASAPI and DirectSound. The
      problem, however is that WASAPI and DirectSound use "<component> (<name>)" format (such as "Speakers (High Definition Audio)"),
      but WinMM does not specify the component name. From my admittedly limited testing, I've notice the component name seems to
      usually fit within the 31 characters of the fixed sized buffer, so what I'm going to do is parse that string for the component
      name, and then concatenate the name from the registry.
    */
    if (!ma_is_guid_null(&pCaps->NameGuid)) {
        WCHAR guidStrW[256];
        if (((MA_PFN_StringFromGUID2)pContext->win32.StringFromGUID2)(&pCaps->NameGuid, guidStrW, ma_countof(guidStrW)) > 0) {
            char guidStr[256];
            char keyStr[1024];
            HKEY hKey;

            WideCharToMultiByte(CP_UTF8, 0, guidStrW, -1, guidStr, sizeof(guidStr), 0, FALSE);

            ma_strcpy_s(keyStr, sizeof(keyStr), "SYSTEM\\CurrentControlSet\\Control\\MediaCategories\\");
            ma_strcat_s(keyStr, sizeof(keyStr), guidStr);

            if (((MA_PFN_RegOpenKeyExA)pContextStateWinmm->RegOpenKeyExA)(HKEY_LOCAL_MACHINE, keyStr, 0, KEY_READ, &hKey) == ERROR_SUCCESS) {
                BYTE nameFromReg[512];
                DWORD nameFromRegSize = sizeof(nameFromReg);
                LONG resultWin32 = ((MA_PFN_RegQueryValueExA)pContextStateWinmm->RegQueryValueExA)(hKey, "Name", 0, NULL, (BYTE*)nameFromReg, (DWORD*)&nameFromRegSize);
                ((MA_PFN_RegCloseKey)pContextStateWinmm->RegCloseKey)(hKey);

                if (resultWin32 == ERROR_SUCCESS) {
                    /* We have the value from the registry, so now we need to construct the name string. */
                    char name[1024];
                    if (ma_strcpy_s(name, sizeof(name), pDeviceInfo->name) == 0) {
                        char* nameBeg = ma_find_last_character(name, '(');
                        if (nameBeg != NULL) {
                            size_t leadingLen = (nameBeg - name);
                            ma_strncpy_s(nameBeg + 1, sizeof(name) - leadingLen, (const char*)nameFromReg, (size_t)-1);

                            /* The closing ")", if it can fit. */
                            if (leadingLen + nameFromRegSize < sizeof(name)-1) {
                                ma_strcat_s(name, sizeof(name), ")");
                            }

                            ma_strncpy_s(pDeviceInfo->name, sizeof(pDeviceInfo->name), name, (size_t)-1);
                        }
                    }
                }
            }
        }
    }


    result = ma_get_best_info_from_formats_flags__winmm(pCaps->dwFormats, pCaps->wChannels, &bitsPerSample, &sampleRate);
    if (result != MA_SUCCESS) {
        return result;
    }

    if (bitsPerSample == 8) {
        format = ma_format_u8;
    } else if (bitsPerSample == 16) {
        format = ma_format_s16;
    } else if (bitsPerSample == 24) {
        format = ma_format_s24;
    } else if (bitsPerSample == 32) {
        format = ma_format_s32;
    } else {
        return MA_FORMAT_NOT_SUPPORTED;
    }

    ma_device_info_add_native_data_format(pDeviceInfo, format, pCaps->wChannels, pCaps->wChannels, sampleRate, sampleRate);

    return MA_SUCCESS;
}

static ma_result ma_context_get_device_info_from_WAVEOUTCAPS2__winmm(ma_context* pContext, MA_WAVEOUTCAPS2A* pCaps, ma_device_info* pDeviceInfo)
{
    MA_WAVECAPSA caps;

    MA_ASSERT(pContext != NULL);
    MA_ASSERT(pCaps != NULL);
    MA_ASSERT(pDeviceInfo != NULL);

    MA_COPY_MEMORY(caps.szPname, pCaps->szPname, sizeof(caps.szPname));
    caps.dwFormats = pCaps->dwFormats;
    caps.wChannels = pCaps->wChannels;
    caps.NameGuid  = pCaps->NameGuid;
    return ma_context_get_device_info_from_WAVECAPS(pContext, &caps, pDeviceInfo);
}

static ma_result ma_context_get_device_info_from_WAVEINCAPS2__winmm(ma_context* pContext, MA_WAVEINCAPS2A* pCaps, ma_device_info* pDeviceInfo)
{
    MA_WAVECAPSA caps;

    MA_ASSERT(pContext != NULL);
    MA_ASSERT(pCaps != NULL);
    MA_ASSERT(pDeviceInfo != NULL);

    MA_COPY_MEMORY(caps.szPname, pCaps->szPname, sizeof(caps.szPname));
    caps.dwFormats = pCaps->dwFormats;
    caps.wChannels = pCaps->wChannels;
    caps.NameGuid  = pCaps->NameGuid;
    return ma_context_get_device_info_from_WAVECAPS(pContext, &caps, pDeviceInfo);
}


static ma_result ma_context_enumerate_devices__winmm(ma_context* pContext, ma_enum_devices_callback_proc callback, void* pUserData)
{
    ma_context_state_winmm* pContextStateWinMM = ma_context_get_backend_state__winmm(pContext);
    UINT playbackDeviceCount;
    UINT captureDeviceCount;
    UINT iPlaybackDevice;
    UINT iCaptureDevice;

    MA_ASSERT(pContext != NULL);
    MA_ASSERT(callback != NULL);

    /* Playback. */
    playbackDeviceCount = pContextStateWinMM->waveOutGetNumDevs();
    for (iPlaybackDevice = 0; iPlaybackDevice < playbackDeviceCount; ++iPlaybackDevice) {
        MA_MMRESULT result;
        MA_WAVEOUTCAPS2A caps;

        MA_ZERO_OBJECT(&caps);

        result = pContextStateWinMM->waveOutGetDevCapsA(iPlaybackDevice, (MA_WAVEOUTCAPSA*)&caps, sizeof(caps));
        if (result == MA_MMSYSERR_NOERROR) {
            ma_device_info deviceInfo;

            MA_ZERO_OBJECT(&deviceInfo);

            /* Default. */
            /* The first enumerated device is the default device. */
            if (iPlaybackDevice == 0) {
                deviceInfo.isDefault = MA_TRUE;
            }

            /* ID. */
            deviceInfo.id.winmm = iPlaybackDevice;

            /* Name and Data Format. */
            if (ma_context_get_device_info_from_WAVEOUTCAPS2__winmm(pContext, &caps, &deviceInfo) == MA_SUCCESS) {
                ma_device_enumeration_result cbResult = callback(ma_device_type_playback, &deviceInfo, pUserData);
                if (cbResult == MA_DEVICE_ENUMERATION_ABORT) {
                    return MA_SUCCESS; /* Enumeration was stopped. */
                }
            }
        }
    }

    /* Capture. */
    captureDeviceCount = pContextStateWinMM->waveInGetNumDevs();
    for (iCaptureDevice = 0; iCaptureDevice < captureDeviceCount; ++iCaptureDevice) {
        MA_MMRESULT result;
        MA_WAVEINCAPS2A caps;

        MA_ZERO_OBJECT(&caps);

        result = pContextStateWinMM->waveInGetDevCapsA(iCaptureDevice, (MA_WAVEINCAPSA*)&caps, sizeof(caps));
        if (result == MA_MMSYSERR_NOERROR) {
            ma_device_info deviceInfo;

            MA_ZERO_OBJECT(&deviceInfo);

            /* Defualt. */
            /* The first enumerated device is the default device. */
            if (iCaptureDevice == 0) {
                deviceInfo.isDefault = MA_TRUE;
            }

            /* ID. */
            deviceInfo.id.winmm = iCaptureDevice;

            /* Name and Data Format. */
            if (ma_context_get_device_info_from_WAVEINCAPS2__winmm(pContext, &caps, &deviceInfo) == MA_SUCCESS) {
                ma_device_enumeration_result cbResult = callback(ma_device_type_capture, &deviceInfo, pUserData);
                if (cbResult == MA_DEVICE_ENUMERATION_ABORT) {
                    return MA_SUCCESS; /* Enumeration was stopped. */
                }
            }
        }
    }

    return MA_SUCCESS;
}


static ma_uint32 ma_calculate_period_size_in_frames_from_descriptor__winmm(const ma_device_descriptor* pDescriptor, ma_uint32 nativeSampleRate)
{
    /* WinMM has a minimum period size of 40ms. */
    ma_uint32 minPeriodSizeInFrames = ma_calculate_buffer_size_in_frames_from_milliseconds(40, nativeSampleRate);
    ma_uint32 periodSizeInFrames;

    periodSizeInFrames = ma_calculate_buffer_size_in_frames_from_descriptor(pDescriptor, nativeSampleRate);
    if (periodSizeInFrames < minPeriodSizeInFrames) {
        periodSizeInFrames = minPeriodSizeInFrames;
    }

    return periodSizeInFrames;
}

static ma_result ma_device_init__winmm(ma_device* pDevice, const void* pDeviceBackendConfig, ma_device_descriptor* pDescriptorPlayback, ma_device_descriptor* pDescriptorCapture, void** ppDeviceState)
{
    ma_device_state_winmm* pDeviceStateWinMM;
    const ma_device_config_winmm* pDeviceConfigWinMM = (const ma_device_config_winmm*)pDeviceBackendConfig;
    ma_device_config_winmm defaultConfigWinMM;
    ma_context_state_winmm* pContextStateWinMM = ma_context_get_backend_state__winmm(ma_device_get_context(pDevice));
    ma_device_type deviceType = ma_device_get_type(pDevice);
    const char* errorMsg = "";
    ma_result errorCode = MA_ERROR;
    ma_result result = MA_SUCCESS;
    ma_uint32 heapSize;
    UINT winMMDeviceIDPlayback = 0;
    UINT winMMDeviceIDCapture  = 0;

    if (pDeviceConfigWinMM == NULL) {
        defaultConfigWinMM = ma_device_config_winmm_init();
        pDeviceConfigWinMM = &defaultConfigWinMM;
    }

    if (deviceType == ma_device_type_loopback) {
        return MA_DEVICE_TYPE_NOT_SUPPORTED;
    }

    /* No exclusive mode with WinMM. */
    if (((deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex) && pDescriptorPlayback->shareMode == ma_share_mode_exclusive) ||
        ((deviceType == ma_device_type_capture  || deviceType == ma_device_type_duplex) && pDescriptorCapture->shareMode  == ma_share_mode_exclusive)) {
        return MA_SHARE_MODE_NOT_SUPPORTED;
    }

    pDeviceStateWinMM = (ma_device_state_winmm*)ma_calloc(sizeof(*pDeviceStateWinMM), ma_device_get_allocation_callbacks(pDevice));
    if (pDeviceStateWinMM == NULL) {
        return MA_OUT_OF_MEMORY;
    }

    if (pDescriptorPlayback->pDeviceID != NULL) {
        winMMDeviceIDPlayback = (UINT)pDescriptorPlayback->pDeviceID->winmm;
    }
    if (pDescriptorCapture->pDeviceID != NULL) {
        winMMDeviceIDCapture = (UINT)pDescriptorCapture->pDeviceID->winmm;
    }

    /* The capture device needs to be initialized first. */
    if (deviceType == ma_device_type_capture || deviceType == ma_device_type_duplex) {
        MA_WAVEINCAPSA caps;
        MA_WAVEFORMATEX wf;
        MA_MMRESULT resultMM;

        /* We use an event to know when a new fragment needs to be enqueued. */
        pDeviceStateWinMM->hEventCapture = CreateEventA(NULL, TRUE, TRUE, NULL);
        if (pDeviceStateWinMM->hEventCapture == NULL) {
            errorMsg = "[WinMM] Failed to create event for fragment enqueuing for the capture device.", errorCode = ma_result_from_GetLastError(GetLastError());
            goto on_error;
        }

        /* The format should be based on the device's actual format. */
        if (pContextStateWinMM->waveInGetDevCapsA(winMMDeviceIDCapture, &caps, sizeof(caps)) != MA_MMSYSERR_NOERROR) {
            errorMsg = "[WinMM] Failed to retrieve internal device caps.", errorCode = MA_FORMAT_NOT_SUPPORTED;
            goto on_error;
        }

        result = ma_formats_flags_to_WAVEFORMATEX__winmm(caps.dwFormats, caps.wChannels, &wf);
        if (result != MA_SUCCESS) {
            errorMsg = "[WinMM] Could not find appropriate format for internal device.", errorCode = result;
            goto on_error;
        }

        resultMM = pContextStateWinMM->waveInOpen(&pDeviceStateWinMM->hDeviceCapture, winMMDeviceIDCapture, &wf, (DWORD_PTR)pDeviceStateWinMM->hEventCapture, (DWORD_PTR)pDevice, MA_CALLBACK_EVENT | MA_WAVE_ALLOWSYNC);
        if (resultMM != MA_MMSYSERR_NOERROR) {
            errorMsg = "[WinMM] Failed to open capture device.", errorCode = MA_FAILED_TO_OPEN_BACKEND_DEVICE;
            goto on_error;
        }

        pDescriptorCapture->format             = ma_format_from_WAVEFORMATEX(&wf);
        pDescriptorCapture->channels           = wf.nChannels;
        pDescriptorCapture->sampleRate         = wf.nSamplesPerSec;
        ma_channel_map_init_standard(ma_standard_channel_map_microsoft, pDescriptorCapture->channelMap, ma_countof(pDescriptorCapture->channelMap), pDescriptorCapture->channels);
        pDescriptorCapture->periodCount        = pDescriptorCapture->periodCount;
        pDescriptorCapture->periodSizeInFrames = ma_calculate_period_size_in_frames_from_descriptor__winmm(pDescriptorCapture, pDescriptorCapture->sampleRate);
    }

    if (deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex) {
        MA_WAVEOUTCAPSA caps;
        MA_WAVEFORMATEX wf;
        MA_MMRESULT resultMM;

        /* We use an event to know when a new fragment needs to be enqueued. */
        pDeviceStateWinMM->hEventPlayback = CreateEventA(NULL, TRUE, TRUE, NULL);
        if (pDeviceStateWinMM->hEventPlayback == NULL) {
            errorMsg = "[WinMM] Failed to create event for fragment enqueuing for the playback device.", errorCode = ma_result_from_GetLastError(GetLastError());
            goto on_error;
        }

        /* The format should be based on the device's actual format. */
        if (pContextStateWinMM->waveOutGetDevCapsA(winMMDeviceIDPlayback, &caps, sizeof(caps)) != MA_MMSYSERR_NOERROR) {
            errorMsg = "[WinMM] Failed to retrieve internal device caps.", errorCode = MA_FORMAT_NOT_SUPPORTED;
            goto on_error;
        }

        result = ma_formats_flags_to_WAVEFORMATEX__winmm(caps.dwFormats, caps.wChannels, &wf);
        if (result != MA_SUCCESS) {
            errorMsg = "[WinMM] Could not find appropriate format for internal device.", errorCode = result;
            goto on_error;
        }

        resultMM = pContextStateWinMM->waveOutOpen(&pDeviceStateWinMM->hDevicePlayback, winMMDeviceIDPlayback, &wf, (DWORD_PTR)pDeviceStateWinMM->hEventPlayback, (DWORD_PTR)pDevice, MA_CALLBACK_EVENT | MA_WAVE_ALLOWSYNC);
        if (resultMM != MA_MMSYSERR_NOERROR) {
            errorMsg = "[WinMM] Failed to open playback device.", errorCode = MA_FAILED_TO_OPEN_BACKEND_DEVICE;
            goto on_error;
        }

        pDescriptorPlayback->format             = ma_format_from_WAVEFORMATEX(&wf);
        pDescriptorPlayback->channels           = wf.nChannels;
        pDescriptorPlayback->sampleRate         = wf.nSamplesPerSec;
        ma_channel_map_init_standard(ma_standard_channel_map_microsoft, pDescriptorPlayback->channelMap, ma_countof(pDescriptorPlayback->channelMap), pDescriptorPlayback->channels);
        pDescriptorPlayback->periodCount        = pDescriptorPlayback->periodCount;
        pDescriptorPlayback->periodSizeInFrames = ma_calculate_period_size_in_frames_from_descriptor__winmm(pDescriptorPlayback, pDescriptorPlayback->sampleRate);
    }

    /*
    The heap allocated data is allocated like so:

    [Capture WAVEHDRs][Playback WAVEHDRs][Capture Intermediary Buffer][Playback Intermediary Buffer]

    We attach this to the end of the device state struct.
    */
    heapSize = 0;
    if (deviceType == ma_device_type_capture || deviceType == ma_device_type_duplex) {
        heapSize += sizeof(MA_WAVEHDR)*pDescriptorCapture->periodCount + (pDescriptorCapture->periodSizeInFrames * pDescriptorCapture->periodCount * ma_get_bytes_per_frame(pDescriptorCapture->format, pDescriptorCapture->channels));
    }
    if (deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex) {
        heapSize += sizeof(MA_WAVEHDR)*pDescriptorPlayback->periodCount + (pDescriptorPlayback->periodSizeInFrames * pDescriptorPlayback->periodCount * ma_get_bytes_per_frame(pDescriptorPlayback->format, pDescriptorPlayback->channels));
    }

    {
        size_t newDeviceStateAllocSize;
        ma_device_state_winmm* pNewDeviceStateWinMM;

        newDeviceStateAllocSize  = 0;
        newDeviceStateAllocSize += ma_align_64(sizeof(*pDeviceStateWinMM));
        newDeviceStateAllocSize += ma_align_64(heapSize);

        pNewDeviceStateWinMM = (ma_device_state_winmm*)ma_realloc(pDeviceStateWinMM, newDeviceStateAllocSize, ma_device_get_allocation_callbacks(pDevice));
        if (pNewDeviceStateWinMM == NULL) {
            goto on_error;
        }

        pDeviceStateWinMM = pNewDeviceStateWinMM;

        pDeviceStateWinMM->_pHeapData = (ma_uint8*)ma_offset_ptr(pDeviceStateWinMM, ma_align_64(sizeof(*pDeviceStateWinMM)));
        MA_ZERO_MEMORY(pDeviceStateWinMM->_pHeapData, heapSize);
    }

    if (deviceType == ma_device_type_capture || deviceType == ma_device_type_duplex) {
        ma_uint32 iPeriod;

        if (deviceType == ma_device_type_capture) {
            pDeviceStateWinMM->pWAVEHDRCapture            = (MA_WAVEHDR*)pDeviceStateWinMM->_pHeapData;
            pDeviceStateWinMM->pIntermediaryBufferCapture = pDeviceStateWinMM->_pHeapData + (sizeof(MA_WAVEHDR)*(pDescriptorCapture->periodCount));
        } else {
            pDeviceStateWinMM->pWAVEHDRCapture            = (MA_WAVEHDR*)pDeviceStateWinMM->_pHeapData;
            pDeviceStateWinMM->pIntermediaryBufferCapture = pDeviceStateWinMM->_pHeapData + (sizeof(MA_WAVEHDR)*(pDescriptorCapture->periodCount + pDescriptorPlayback->periodCount));
        }

        /* Prepare headers. */
        for (iPeriod = 0; iPeriod < pDescriptorCapture->periodCount; ++iPeriod) {
            ma_uint32 periodSizeInBytes = ma_get_period_size_in_bytes(pDescriptorCapture->periodSizeInFrames, pDescriptorCapture->format, pDescriptorCapture->channels);

            pDeviceStateWinMM->pWAVEHDRCapture[iPeriod].lpData         = (char*)(pDeviceStateWinMM->pIntermediaryBufferCapture + (periodSizeInBytes*iPeriod));
            pDeviceStateWinMM->pWAVEHDRCapture[iPeriod].dwBufferLength = periodSizeInBytes;
            pDeviceStateWinMM->pWAVEHDRCapture[iPeriod].dwFlags        = 0L;
            pDeviceStateWinMM->pWAVEHDRCapture[iPeriod].dwLoops        = 0L;
            pContextStateWinMM->waveInPrepareHeader(pDeviceStateWinMM->hDeviceCapture, &pDeviceStateWinMM->pWAVEHDRCapture[iPeriod], sizeof(MA_WAVEHDR));
        }
    }

    if (deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex) {
        ma_uint32 iPeriod;

        if (deviceType == ma_device_type_playback) {
            pDeviceStateWinMM->pWAVEHDRPlayback            = (MA_WAVEHDR*)pDeviceStateWinMM->_pHeapData;
            pDeviceStateWinMM->pIntermediaryBufferPlayback = pDeviceStateWinMM->_pHeapData + (sizeof(MA_WAVEHDR)*pDescriptorPlayback->periodCount);
        } else {
            pDeviceStateWinMM->pWAVEHDRPlayback            = (MA_WAVEHDR*)pDeviceStateWinMM->_pHeapData + pDescriptorCapture->periodCount;
            pDeviceStateWinMM->pIntermediaryBufferPlayback = pDeviceStateWinMM->_pHeapData + (sizeof(MA_WAVEHDR)*(pDescriptorCapture->periodCount + pDescriptorPlayback->periodCount)) + (pDescriptorCapture->periodSizeInFrames*pDescriptorCapture->periodCount*ma_get_bytes_per_frame(pDescriptorCapture->format, pDescriptorCapture->channels));
        }

        /* Prepare headers. */
        for (iPeriod = 0; iPeriod < pDescriptorPlayback->periodCount; ++iPeriod) {
            ma_uint32 periodSizeInBytes = ma_get_period_size_in_bytes(pDescriptorPlayback->periodSizeInFrames, pDescriptorPlayback->format, pDescriptorPlayback->channels);

            pDeviceStateWinMM->pWAVEHDRPlayback[iPeriod].lpData         = (char*)(pDeviceStateWinMM->pIntermediaryBufferPlayback + (periodSizeInBytes*iPeriod));
            pDeviceStateWinMM->pWAVEHDRPlayback[iPeriod].dwBufferLength = periodSizeInBytes;
            pDeviceStateWinMM->pWAVEHDRPlayback[iPeriod].dwFlags        = 0L;
            pDeviceStateWinMM->pWAVEHDRPlayback[iPeriod].dwLoops        = 0L;
            pContextStateWinMM->waveOutPrepareHeader(pDeviceStateWinMM->hDevicePlayback, &pDeviceStateWinMM->pWAVEHDRPlayback[iPeriod], sizeof(MA_WAVEHDR));

            /*
            We use the WHDR_DONE flag to determine whether not not a buffer is available for writing. Since in playback
            mode we want buffers to be writable from the start, we will set the flag here at initialization time.
            */
            pDeviceStateWinMM->pWAVEHDRPlayback[iPeriod].dwFlags |= MA_WHDR_DONE;
        }
    }

    *ppDeviceState = pDeviceStateWinMM;

    return MA_SUCCESS;

on_error:
    if (pDevice->type == ma_device_type_capture || pDevice->type == ma_device_type_duplex) {
        if (pDeviceStateWinMM->pWAVEHDRCapture != NULL) {
            ma_uint32 iPeriod;
            for (iPeriod = 0; iPeriod < pDescriptorCapture->periodCount; ++iPeriod) {
                pContextStateWinMM->waveInUnprepareHeader(pDeviceStateWinMM->hDeviceCapture, &pDeviceStateWinMM->pWAVEHDRCapture[iPeriod], sizeof(MA_WAVEHDR));
            }
        }

        pContextStateWinMM->waveInClose(pDeviceStateWinMM->hDeviceCapture);
    }

    if (pDevice->type == ma_device_type_playback || pDevice->type == ma_device_type_duplex) {
        if (pDeviceStateWinMM->pWAVEHDRCapture != NULL) {
            ma_uint32 iPeriod;
            for (iPeriod = 0; iPeriod < pDescriptorPlayback->periodCount; ++iPeriod) {
                pContextStateWinMM->waveOutUnprepareHeader(pDeviceStateWinMM->hDevicePlayback, &pDeviceStateWinMM->pWAVEHDRPlayback[iPeriod], sizeof(MA_WAVEHDR));
            }
        }

        pContextStateWinMM->waveOutClose(pDeviceStateWinMM->hDevicePlayback);
    }

    ma_free(pDeviceStateWinMM, ma_device_get_allocation_callbacks(pDevice));

    if (errorMsg != NULL && errorMsg[0] != '\0') {
        ma_log_postf(ma_device_get_log(pDevice), MA_LOG_LEVEL_ERROR, "%s", errorMsg);
    }

    return errorCode;
}

static void ma_device_uninit__winmm(ma_device* pDevice)
{
    ma_device_state_winmm* pDeviceStateWinMM = ma_device_get_backend_state__winmm(pDevice);
    ma_context_state_winmm* pContextStateWinMM = ma_context_get_backend_state__winmm(ma_device_get_context(pDevice));
    ma_device_type deviceType = ma_device_get_type(pDevice);

    if (deviceType == ma_device_type_capture || deviceType == ma_device_type_duplex) {
        pContextStateWinMM->waveInClose(pDeviceStateWinMM->hDeviceCapture);
        CloseHandle(pDeviceStateWinMM->hEventCapture);
    }

    if (deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex) {
        pContextStateWinMM->waveOutReset(pDeviceStateWinMM->hDevicePlayback);
        pContextStateWinMM->waveOutClose(pDeviceStateWinMM->hDevicePlayback);
        CloseHandle(pDeviceStateWinMM->hEventPlayback);
    }

    ma_free(pDeviceStateWinMM, ma_device_get_allocation_callbacks(pDevice));
}

static ma_result ma_device_start__winmm(ma_device* pDevice)
{
    ma_device_state_winmm* pDeviceStateWinMM = ma_device_get_backend_state__winmm(pDevice);
    ma_context_state_winmm* pContextStateWinMM = ma_context_get_backend_state__winmm(ma_device_get_context(pDevice));
    ma_device_type deviceType = ma_device_get_type(pDevice);

    if (deviceType == ma_device_type_capture || deviceType == ma_device_type_duplex) {
        MA_MMRESULT resultMM;
        MA_WAVEHDR* pWAVEHDR;
        ma_uint32 iPeriod;

        pWAVEHDR = pDeviceStateWinMM->pWAVEHDRCapture;

        /* Make sure the event is reset to a non-signaled state to ensure we don't prematurely return from WaitForSingleObject(). */
        ResetEvent(pDeviceStateWinMM->hEventCapture);

        /* To start the device we attach all of the buffers and then start it. As the buffers are filled with data we will get notifications. */
        for (iPeriod = 0; iPeriod < pDevice->capture.internalPeriods; ++iPeriod) {
            resultMM = pContextStateWinMM->waveInAddBuffer(pDeviceStateWinMM->hDeviceCapture, &pDeviceStateWinMM->pWAVEHDRCapture[iPeriod], sizeof(MA_WAVEHDR));
            if (resultMM != MA_MMSYSERR_NOERROR) {
                ma_log_post(ma_device_get_log(pDevice), MA_LOG_LEVEL_ERROR, "[WinMM] Failed to attach input buffers to capture device in preparation for capture.");
                return ma_result_from_MMRESULT(resultMM);
            }
        }

        /* Capture devices need to be explicitly started, unlike playback devices. */
        resultMM = pContextStateWinMM->waveInStart(pDeviceStateWinMM->hDeviceCapture);
        if (resultMM != MA_MMSYSERR_NOERROR) {
            ma_log_post(ma_device_get_log(pDevice), MA_LOG_LEVEL_ERROR, "[WinMM] Failed to start backend device.");
            return ma_result_from_MMRESULT(resultMM);
        }
    }

    if (deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex) {
        /* Don't need to do anything for playback. It'll be started automatically in ma_device_start__winmm(). */
    }

    return MA_SUCCESS;
}

static ma_result ma_device_stop__winmm(ma_device* pDevice)
{
    ma_device_state_winmm* pDeviceStateWinMM = ma_device_get_backend_state__winmm(pDevice);
    ma_context_state_winmm* pContextStateWinMM = ma_context_get_backend_state__winmm(ma_device_get_context(pDevice));
    ma_device_type deviceType = ma_device_get_type(pDevice);
    MA_MMRESULT resultMM;

    if (deviceType == ma_device_type_capture || deviceType == ma_device_type_duplex) {
        if (pDeviceStateWinMM->hDeviceCapture == NULL) {
            return MA_INVALID_ARGS;
        }

        resultMM = pContextStateWinMM->waveInReset(pDeviceStateWinMM->hDeviceCapture);
        if (resultMM != MA_MMSYSERR_NOERROR) {
            ma_log_post(ma_device_get_log(pDevice), MA_LOG_LEVEL_WARNING, "[WinMM] WARNING: Failed to reset capture device.");
        }
    }

    if (deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex) {
        ma_uint32 iPeriod;
        MA_WAVEHDR* pWAVEHDR;

        if (pDeviceStateWinMM->hDevicePlayback == NULL) {
            return MA_INVALID_ARGS;
        }

        /* We need to drain the device. To do this we just loop over each header and if it's locked just wait for the event. */
        pWAVEHDR = pDeviceStateWinMM->pWAVEHDRPlayback;
        for (iPeriod = 0; iPeriod < pDevice->playback.internalPeriods; iPeriod += 1) {
            if (WaitForSingleObject(pDeviceStateWinMM->hEventPlayback, INFINITE) != WAIT_OBJECT_0) {
                break;  /* An error occurred so just abandon ship and stop the device without draining. */
            }
        }

        resultMM = pContextStateWinMM->waveOutReset(pDeviceStateWinMM->hDevicePlayback);
        if (resultMM != MA_MMSYSERR_NOERROR) {
            ma_log_post(ma_device_get_log(pDevice), MA_LOG_LEVEL_WARNING, "[WinMM] WARNING: Failed to reset playback device.");
        }
    }

    return MA_SUCCESS;
}

static ma_result ma_device_step__winmm(ma_device* pDevice, ma_blocking_mode blockingMode)
{
    ma_device_state_winmm* pDeviceStateWinMM = ma_device_get_backend_state__winmm(pDevice);
    ma_context_state_winmm* pContextStateWinMM = ma_context_get_backend_state__winmm(ma_device_get_context(pDevice));
    ma_device_type deviceType = ma_device_get_type(pDevice);
    HANDLE handles[2];
    DWORD handleCount;
    DWORD timeout = (blockingMode == MA_BLOCKING_MODE_BLOCKING) ? INFINITE : 0;
    DWORD waitResult;
    MA_MMRESULT resultMM;

    handleCount = 0;
    if (deviceType == ma_device_type_capture || deviceType == ma_device_type_duplex) {
        handles[handleCount++] = pDeviceStateWinMM->hEventCapture;
    }
    if (deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex) {
        handles[handleCount++] = pDeviceStateWinMM->hEventPlayback;
    }

    waitResult = WaitForMultipleObjects(handleCount, handles, FALSE, timeout);
    if (waitResult == WAIT_FAILED) {
        return MA_ERROR;    /* Backend is in an erroneous state. */
    }

    if (!ma_device_is_started(pDevice)) {
        return MA_DEVICE_NOT_STARTED;
    }

    if (waitResult >= WAIT_OBJECT_0 && waitResult <= WAIT_OBJECT_0 + handleCount-1) {
        /* Something is available for processing. */
        HANDLE handle = handles[waitResult - WAIT_OBJECT_0];
        ma_uint32 frameCount;

        /* Capture. */
        if (handle == pDeviceStateWinMM->hEventCapture && (deviceType == ma_device_type_capture || deviceType == ma_device_type_duplex)) {
            MA_WAVEHDR* pWAVEHDR = pDeviceStateWinMM->pWAVEHDRCapture;

            /* Consume any completed header. */
            while ((pWAVEHDR[pDeviceStateWinMM->iNextHeaderCapture].dwFlags & MA_WHDR_DONE) != 0) {
                pWAVEHDR[pDeviceStateWinMM->iNextHeaderCapture].dwFlags &= ~MA_WHDR_DONE;

                frameCount = pWAVEHDR[pDeviceStateWinMM->iNextHeaderCapture].dwBufferLength / ma_get_bytes_per_frame(pDevice->capture.internalFormat, pDevice->capture.internalChannels);
                ma_device_handle_backend_data_callback(pDevice, NULL, pWAVEHDR[pDeviceStateWinMM->iNextHeaderCapture].lpData, frameCount);

                /* The device will be started here. */
                resultMM = pContextStateWinMM->waveInAddBuffer(pDeviceStateWinMM->hDeviceCapture, &pDeviceStateWinMM->pWAVEHDRCapture[pDeviceStateWinMM->iNextHeaderCapture], sizeof(MA_WAVEHDR));
                if (resultMM != MA_MMSYSERR_NOERROR) {
                    ma_log_post(ma_device_get_log(pDevice), MA_LOG_LEVEL_ERROR, "[WinMM] waveInAddBuffer() failed.");
                    return ma_result_from_MMRESULT(resultMM);
                }

                /* Make sure we move to the next header. */
                pDeviceStateWinMM->iNextHeaderCapture = (pDeviceStateWinMM->iNextHeaderCapture + 1) % pDevice->capture.internalPeriods;
            }

            /* Make sure the event is reset to a non-signaled state to ensure we don't prematurely return from WaitForSingleObject(). */
            ResetEvent(pDeviceStateWinMM->hEventCapture);
        }

        /* Playback. */
        if (handle == pDeviceStateWinMM->hEventPlayback && (deviceType == ma_device_type_playback || deviceType == ma_device_type_duplex)) {
            MA_WAVEHDR* pWAVEHDR = pDeviceStateWinMM->pWAVEHDRPlayback;

            /* Fill out any completed header with fresh data. */
            while ((pWAVEHDR[pDeviceStateWinMM->iNextHeaderPlayback].dwFlags & MA_WHDR_DONE) != 0) {
                pWAVEHDR[pDeviceStateWinMM->iNextHeaderPlayback].dwFlags &= ~MA_WHDR_DONE;

                frameCount = pWAVEHDR[pDeviceStateWinMM->iNextHeaderPlayback].dwBufferLength / ma_get_bytes_per_frame(pDevice->playback.internalFormat, pDevice->playback.internalChannels);
                ma_device_handle_backend_data_callback(pDevice, pWAVEHDR[pDeviceStateWinMM->iNextHeaderPlayback].lpData, NULL, frameCount);

                /* The device will be started here. */
                resultMM = pContextStateWinMM->waveOutWrite(pDeviceStateWinMM->hDevicePlayback, &pWAVEHDR[pDeviceStateWinMM->iNextHeaderPlayback], sizeof(MA_WAVEHDR));
                if (resultMM != MA_MMSYSERR_NOERROR) {
                    ma_log_post(ma_device_get_log(pDevice), MA_LOG_LEVEL_ERROR, "[WinMM] waveOutWrite() failed.");
                    return ma_result_from_MMRESULT(resultMM);
                }

                /* Make sure we move to the next header. */
                pDeviceStateWinMM->iNextHeaderPlayback = (pDeviceStateWinMM->iNextHeaderPlayback + 1) % pDevice->playback.internalPeriods;
            }

            /* Make sure the event is reset to a non-signaled state to ensure we don't prematurely return from WaitForSingleObject(). */
            ResetEvent(pDeviceStateWinMM->hEventPlayback);
        }
    } else {
        /* Most likely a timeout in non-blocking mode. Nothing to do. */
    }

    return MA_SUCCESS;
}

static ma_device_backend_vtable ma_gDeviceBackendVTable_WinMM =
{
    ma_backend_info__winmm,
    ma_context_init__winmm,
    ma_context_uninit__winmm,
    ma_context_enumerate_devices__winmm,
    ma_device_init__winmm,
    ma_device_uninit__winmm,
    ma_device_start__winmm,
    ma_device_stop__winmm,
    ma_device_step__winmm,
    NULL    /* onDeviceWakeup */
};

