static ma_result ma_wait_for_operation__pulseaudio(ma_context_state_pulseaudio* pContextStatePulseAudio, ma_pa_mainloop* pMainLoop, ma_pa_operation* pOP)
{
    int resultPA;
    ma_pa_operation_state_t state;

    MA_ASSERT(pContextStatePulseAudio != NULL);
    MA_ASSERT(pOP != NULL);

    for (;;) {
        state = pContextStatePulseAudio->pa_operation_get_state(pOP);
        if (state != MA_PA_OPERATION_RUNNING) {
            break;  /* Done. */
        }

        resultPA = pContextStatePulseAudio->pa_mainloop_iterate(pMainLoop, 1, NULL);
        if (resultPA < 0) {
            return ma_result_from_pulseaudio(resultPA);
        }
    }

    return MA_SUCCESS;
}

static ma_result ma_wait_for_operation_and_unref__pulseaudio(ma_context_state_pulseaudio* pContextStatePulseAudio, ma_pa_mainloop* pMainLoop, ma_pa_operation* pOP)
{
    ma_result result;

    if (pOP == NULL) {
        return MA_INVALID_ARGS;
    }

    result = ma_wait_for_operation__pulseaudio(pContextStatePulseAudio, pMainLoop, pOP);
    pContextStatePulseAudio->pa_operation_unref(pOP);

    return result;
}

static ma_result ma_wait_for_pa_context_to_connect__pulseaudio(ma_context* pContext, ma_context_state_pulseaudio* pContextStatePulseAudio, ma_pa_mainloop* pMainLoop, ma_pa_context* pPulseContext)
{
    int resultPA;
    ma_pa_context_state_t state;

    for (;;) {
        state = pContextStatePulseAudio->pa_context_get_state(pPulseContext);
        if (state == MA_PA_CONTEXT_READY) {
            break;  /* Done. */
        }

        if (state == MA_PA_CONTEXT_FAILED || state == MA_PA_CONTEXT_TERMINATED) {
            ma_log_postf(ma_context_get_log(pContext), MA_LOG_LEVEL_ERROR, "[PulseAudio] An error occurred while connecting the PulseAudio context.");
            return MA_ERROR;
        }

        resultPA = pContextStatePulseAudio->pa_mainloop_iterate(pMainLoop, 1, NULL);
        if (resultPA < 0) {
            return ma_result_from_pulseaudio(resultPA);
        }
    }

    /* Should never get here. */
    return MA_SUCCESS;
}

static ma_result ma_wait_for_pa_stream_to_connect__pulseaudio(ma_context* pContext, ma_context_state_pulseaudio* pContextStatePulseAudio, ma_pa_mainloop* pMainLoop, ma_pa_stream* pStream)
{
    int resultPA;
    ma_pa_stream_state_t state;

    for (;;) {
        state = pContextStatePulseAudio->pa_stream_get_state(pStream);
        if (state == MA_PA_STREAM_READY) {
            break;  /* Done. */
        }

        if (state == MA_PA_STREAM_FAILED || state == MA_PA_STREAM_TERMINATED) {
            ma_log_postf(ma_context_get_log(pContext), MA_LOG_LEVEL_ERROR, "[PulseAudio] An error occurred while connecting the PulseAudio stream.");
            return MA_ERROR;
        }

        resultPA = pContextStatePulseAudio->pa_mainloop_iterate(pMainLoop, 1, NULL);
        if (resultPA < 0) {
            return ma_result_from_pulseaudio(resultPA);
        }
    }

    return MA_SUCCESS;
}


static ma_result ma_init_pa_mainloop_and_pa_context__pulseaudio(ma_context* pContext, ma_context_state_pulseaudio* pContextStatePulseAudio, const char* pApplicationName, const char* pServerName, ma_bool32 tryAutoSpawn, ma_pa_mainloop** ppMainLoop, ma_pa_context** ppPulseContext)
{
    ma_result result;
    ma_pa_mainloop* pMainLoop;
    ma_pa_context* pPulseContext;

    MA_ASSERT(ppMainLoop     != NULL);
    MA_ASSERT(ppPulseContext != NULL);

    pMainLoop = pContextStatePulseAudio->pa_mainloop_new();
    if (pMainLoop == NULL) {
        ma_log_postf(ma_context_get_log(pContext), MA_LOG_LEVEL_ERROR, "[PulseAudio] Failed to create mainloop.");
        return MA_FAILED_TO_INIT_BACKEND;
    }

    pPulseContext = pContextStatePulseAudio->pa_context_new(pContextStatePulseAudio->pa_mainloop_get_api(pMainLoop), pApplicationName);
    if (pPulseContext == NULL) {
        ma_log_postf(ma_context_get_log(pContext), MA_LOG_LEVEL_ERROR, "[PulseAudio] Failed to create PulseAudio context.");
        pContextStatePulseAudio->pa_mainloop_free(pMainLoop);
        return MA_FAILED_TO_INIT_BACKEND;
    }

    result = ma_result_from_pulseaudio(pContextStatePulseAudio->pa_context_connect(pPulseContext, pServerName, (tryAutoSpawn) ? MA_PA_CONTEXT_NOFLAGS : MA_PA_CONTEXT_NOAUTOSPAWN, NULL));
    if (result != MA_SUCCESS) {
        ma_log_postf(ma_context_get_log(pContext), MA_LOG_LEVEL_ERROR, "[PulseAudio] Failed to connect PulseAudio context.");
        pContextStatePulseAudio->pa_context_unref(pPulseContext);
        pContextStatePulseAudio->pa_mainloop_free(pMainLoop);
        return result;
    }

    /* PulseAudio uses an asynchronous initialization process, whereas miniaudio is synchronous. We need to wait for PulseAudio to finish. */
    result = ma_wait_for_pa_context_to_connect__pulseaudio(pContext, pContextStatePulseAudio, pMainLoop, pPulseContext);
    if (result != MA_SUCCESS) {
        ma_log_postf(ma_context_get_log(pContext), MA_LOG_LEVEL_ERROR, "[PulseAudio] Waiting for connection failed.");
        pContextStatePulseAudio->pa_context_unref(pPulseContext);
        pContextStatePulseAudio->pa_mainloop_free(pMainLoop);
        return result;
    }

    *ppMainLoop     = pMainLoop;
    *ppPulseContext = pPulseContext;

    return MA_SUCCESS;
}


static void ma_device_sink_info_callback(ma_pa_context* pPulseContext, const ma_pa_sink_info* pInfo, int endOfList, void* pUserData)
{
    ma_pa_sink_info* pInfoOut;

    if (endOfList > 0) {
        return;
    }

    /*
    There has been a report that indicates that pInfo can be null which results
    in a null pointer dereference below. We'll check for this for safety.
    */
    if (pInfo == NULL) {
        return;
    }

    pInfoOut = (ma_pa_sink_info*)pUserData;
    MA_ASSERT(pInfoOut != NULL);

    *pInfoOut = *pInfo;

    (void)pPulseContext; /* Unused. */
}

static void ma_device_source_info_callback(ma_pa_context* pPulseContext, const ma_pa_source_info* pInfo, int endOfList, void* pUserData)
{
    ma_pa_source_info* pInfoOut;

    if (endOfList > 0) {
        return;
    }

    /*
    There has been a report that indicates that pInfo can be null which results
    in a null pointer dereference below. We'll check for this for safety.
    */
    if (pInfo == NULL) {
        return;
    }

    pInfoOut = (ma_pa_source_info*)pUserData;
    MA_ASSERT(pInfoOut != NULL);

    *pInfoOut = *pInfo;

    (void)pPulseContext; /* Unused. */
}


static ma_result ma_context_get_sink_info__pulseaudio(ma_context_state_pulseaudio* pContextStatePulseAudio, const char* pDeviceName, ma_pa_sink_info* pSinkInfo)
{
    ma_pa_operation* pOP;

    pOP = pContextStatePulseAudio->pa_context_get_sink_info_by_name(pContextStatePulseAudio->pPulseContext, pDeviceName, ma_device_sink_info_callback, pSinkInfo);
    if (pOP == NULL) {
        return MA_ERROR;
    }

    return ma_wait_for_operation_and_unref__pulseaudio(pContextStatePulseAudio, pContextStatePulseAudio->pMainLoop, pOP);
}

static ma_result ma_context_get_source_info__pulseaudio(ma_context_state_pulseaudio* pContextStatePulseAudio, const char* pDeviceName, ma_pa_source_info* pSourceInfo)
{
    ma_pa_operation* pOP;

    pOP = pContextStatePulseAudio->pa_context_get_source_info_by_name(pContextStatePulseAudio->pPulseContext, pDeviceName, ma_device_source_info_callback, pSourceInfo);
    if (pOP == NULL) {
        return MA_ERROR;
    }

    return ma_wait_for_operation_and_unref__pulseaudio(pContextStatePulseAudio, pContextStatePulseAudio->pMainLoop, pOP);
}

static ma_result ma_context_get_default_device_index__pulseaudio(ma_context_state_pulseaudio* pContextStatePulseAudio, ma_device_type deviceType, ma_uint32* pIndex)
{
    ma_result result;

    MA_ASSERT(pContextStatePulseAudio != NULL);
    MA_ASSERT(pIndex != NULL);

    if (pIndex != NULL) {
        *pIndex = (ma_uint32)-1;
    }

    if (deviceType == ma_device_type_playback) {
        ma_pa_sink_info sinkInfo;
        result = ma_context_get_sink_info__pulseaudio(pContextStatePulseAudio, NULL, &sinkInfo);
        if (result != MA_SUCCESS) {
            return result;
        }

        if (pIndex != NULL) {
            *pIndex = sinkInfo.index;
        }
    }

    if (deviceType == ma_device_type_capture) {
        ma_pa_source_info sourceInfo;
        result = ma_context_get_source_info__pulseaudio(pContextStatePulseAudio, NULL, &sourceInfo);
        if (result != MA_SUCCESS) {
            return result;
        }

        if (pIndex != NULL) {
            *pIndex = sourceInfo.index;
        }
    }

    return MA_SUCCESS;
}


