        pContextStateAAudio->AAudioStreamBuilder_delete                    = (MA_PFN_AAudioStreamBuilder_delete                   )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_delete");
        pContextStateAAudio->AAudioStreamBuilder_setDeviceId               = (MA_PFN_AAudioStreamBuilder_setDeviceId              )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setDeviceId");
        pContextStateAAudio->AAudioStreamBuilder_setDirection              = (MA_PFN_AAudioStreamBuilder_setDirection             )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setDirection");
        pContextStateAAudio->AAudioStreamBuilder_setSharingMode            = (MA_PFN_AAudioStreamBuilder_setSharingMode           )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setSharingMode");
        pContextStateAAudio->AAudioStreamBuilder_setFormat                 = (MA_PFN_AAudioStreamBuilder_setFormat                )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setFormat");
        pContextStateAAudio->AAudioStreamBuilder_setChannelCount           = (MA_PFN_AAudioStreamBuilder_setChannelCount          )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setChannelCount");
        pContextStateAAudio->AAudioStreamBuilder_setSampleRate             = (MA_PFN_AAudioStreamBuilder_setSampleRate            )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setSampleRate");
        pContextStateAAudio->AAudioStreamBuilder_setBufferCapacityInFrames = (MA_PFN_AAudioStreamBuilder_setBufferCapacityInFrames)ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setBufferCapacityInFrames");
        pContextStateAAudio->AAudioStreamBuilder_setFramesPerDataCallback  = (MA_PFN_AAudioStreamBuilder_setFramesPerDataCallback )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setFramesPerDataCallback");
        pContextStateAAudio->AAudioStreamBuilder_setDataCallback           = (MA_PFN_AAudioStreamBuilder_setDataCallback          )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setDataCallback");
        pContextStateAAudio->AAudioStreamBuilder_setErrorCallback          = (MA_PFN_AAudioStreamBuilder_setErrorCallback         )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setErrorCallback");
        pContextStateAAudio->AAudioStreamBuilder_setPerformanceMode        = (MA_PFN_AAudioStreamBuilder_setPerformanceMode       )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setPerformanceMode");
        pContextStateAAudio->AAudioStreamBuilder_setUsage                  = (MA_PFN_AAudioStreamBuilder_setUsage                 )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setUsage");
        pContextStateAAudio->AAudioStreamBuilder_setContentType            = (MA_PFN_AAudioStreamBuilder_setContentType           )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setContentType");
        pContextStateAAudio->AAudioStreamBuilder_setInputPreset            = (MA_PFN_AAudioStreamBuilder_setInputPreset           )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setInputPreset");
        pContextStateAAudio->AAudioStreamBuilder_setAllowedCapturePolicy   = (MA_PFN_AAudioStreamBuilder_setAllowedCapturePolicy  )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_setAllowedCapturePolicy");
        pContextStateAAudio->AAudioStreamBuilder_openStream                = (MA_PFN_AAudioStreamBuilder_openStream               )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStreamBuilder_openStream");
        pContextStateAAudio->AAudioStream_close                            = (MA_PFN_AAudioStream_close                           )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_close");
        pContextStateAAudio->AAudioStream_getState                         = (MA_PFN_AAudioStream_getState                        )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_getState");
