        pContextStateAAudio->AAudioStream_getFormat                        = (MA_PFN_AAudioStream_getFormat                       )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_getFormat");
        pContextStateAAudio->AAudioStream_getChannelCount                  = (MA_PFN_AAudioStream_getChannelCount                 )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_getChannelCount");
        pContextStateAAudio->AAudioStream_getSampleRate                    = (MA_PFN_AAudioStream_getSampleRate                   )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_getSampleRate");
        pContextStateAAudio->AAudioStream_getBufferCapacityInFrames        = (MA_PFN_AAudioStream_getBufferCapacityInFrames       )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_getBufferCapacityInFrames");
        pContextStateAAudio->AAudioStream_getFramesPerDataCallback         = (MA_PFN_AAudioStream_getFramesPerDataCallback        )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_getFramesPerDataCallback");
        pContextStateAAudio->AAudioStream_getFramesPerBurst                = (MA_PFN_AAudioStream_getFramesPerBurst               )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_getFramesPerBurst");
        pContextStateAAudio->AAudioStream_requestStart                     = (MA_PFN_AAudioStream_requestStart                    )ma_dlsym(ma_context_get_log(pContext), pContextStateAAudio->hAAudio, "AAudioStream_requestStart");
