        pContextStateAAudio->AAudioStream_close                            = AAudioStream_close;
        pContextStateAAudio->AAudioStream_getState                         = AAudioStream_getState;
        pContextStateAAudio->AAudioStream_waitForStateChange               = AAudioStream_waitForStateChange;
        pContextStateAAudio->AAudioStream_getFormat                        = AAudioStream_getFormat;
        pContextStateAAudio->AAudioStream_getChannelCount                  = AAudioStream_getChannelCount;
        pContextStateAAudio->AAudioStream_getSampleRate                    = AAudioStream_getSampleRate;
